#!/usr/bin/env python3
# blind_j6.py -- TASK-20260923-21ae7f, joint J6 of REVIEW-FROB-20260923-458763.
#
# Blind re-derivation of Q1, Q2, Q3 exactly as defined in
# coordination/review/frob-20260923-458763/blind-inputs.yaml, written from those
# definitions alone.  Pure Python 3 (own finite-field and polynomial code).
# sympy is used ONLY as an independent cross-check (factor_list over prime
# fields, n_order, isprime); mpmath and decimal only for the log2 margins.
#
# Output: human-readable log on stdout, and the machine-readable results as a
# single JSON document after the line "=== RESULTS JSON ===".
import sys, json, math, random, time, platform, itertools
from fractions import Fraction
from decimal import Decimal, getcontext
import mpmath
import sympy
from sympy.ntheory import n_order

T0 = time.time()


def log(*a):
    print(" ".join(str(x) for x in a), flush=True)


# =============================================================================
# 1. Small fields F_q, q in {2, 3, 4, 8}
# =============================================================================
class SmallField:
    """F_q with elements encoded as ints 0..q-1.
    q=2,3 : Z/qZ.
    q=4   : F_2[a]/(a^2+a+1), int bit i = coefficient of a^i.
    q=8   : F_2[a]/(a^3+a+1), int bit i = coefficient of a^i.
    The integer 1 is the multiplicative identity in every model."""

    def __init__(self, q):
        self.q = q
        if q in (2, 3):
            self.p, self.k, self.model = q, 1, "Z/%dZ" % q
            addf = lambda a, b: (a + b) % q
            mulf = lambda a, b: (a * b) % q
        elif q in (4, 8):
            self.p = 2
            self.k = {4: 2, 8: 3}[q]
            mp = {4: 0b111, 8: 0b1011}[q]
            self.model = {4: "F_2[a]/(a^2+a+1)", 8: "F_2[a]/(a^3+a+1)"}[q]

            def mulf(a, b):
                r = 0
                while b:
                    if b & 1:
                        r ^= a
                    b >>= 1
                    a <<= 1
                    if a & q:
                        a ^= mp
                return r

            addf = lambda a, b: a ^ b
        else:
            raise ValueError(q)
        R = range(q)
        self.ADD = [[addf(a, b) for b in R] for a in R]
        self.MUL = [[mulf(a, b) for b in R] for a in R]
        self.NEG = [[b for b in R if self.ADD[a][b] == 0][0] for a in R]
        self.SUB = [[self.ADD[a][self.NEG[b]] for b in R] for a in R]
        self.INV = [None] + [[b for b in R if self.MUL[a][b] == 1][0] for a in range(1, q)]
        # full field-axiom check (q^3 <= 512 triples)
        for a in R:
            for b in R:
                assert self.ADD[a][b] == self.ADD[b][a]
                assert self.MUL[a][b] == self.MUL[b][a]
                for c in R:
                    assert self.ADD[self.ADD[a][b]][c] == self.ADD[a][self.ADD[b][c]]
                    assert self.MUL[self.MUL[a][b]][c] == self.MUL[a][self.MUL[b][c]]
                    assert self.MUL[a][self.ADD[b][c]] == self.ADD[self.MUL[a][b]][self.MUL[a][c]]
        for a in R:  # c^q = c on F_q
            x = 1
            for _ in range(q):
                x = self.MUL[x][a]
            assert x == a


# =============================================================================
# 2. Polynomials over F_q: lists of ints, index = degree, no trailing zeros
# =============================================================================
def trim(a):
    while a and a[-1] == 0:
        a.pop()
    return a


def deg(a):
    return len(a) - 1


def padd(F, a, b):
    if len(a) < len(b):
        a, b = b, a
    r = a[:]
    for i, c in enumerate(b):
        if c:
            r[i] = F.ADD[r[i]][c]
    return trim(r)


def pneg(F, a):
    return [F.NEG[c] for c in a]


def psub(F, a, b):
    return padd(F, a, pneg(F, b))


def pscale(F, c, a):
    if c == 0:
        return []
    row = F.MUL[c]
    return trim([row[x] for x in a])


def pmul(F, a, b):
    if not a or not b:
        return []
    r = [0] * (len(a) + len(b) - 1)
    MUL, ADD = F.MUL, F.ADD
    bnz = [(j, bj) for j, bj in enumerate(b) if bj]
    for i, ai in enumerate(a):
        if ai == 0:
            continue
        row = MUL[ai]
        for j, bj in bnz:
            r[i + j] = ADD[r[i + j]][row[bj]]
    return trim(r)


def pdivmod(F, a, b):
    assert b, "division by zero polynomial"
    r = a[:]
    db = len(b) - 1
    inv = F.INV[b[-1]]
    if len(r) - 1 < db:
        return [], trim(r)
    qt = [0] * (len(r) - db)
    MUL, SUB = F.MUL, F.SUB
    bnz = [(j, bj) for j, bj in enumerate(b) if bj]
    for i in range(len(r) - 1, db - 1, -1):
        c = r[i]
        if c == 0:
            continue
        c = MUL[c][inv]
        qt[i - db] = c
        row = MUL[c]
        off = i - db
        for j, bj in bnz:
            r[off + j] = SUB[r[off + j]][row[bj]]
    return trim(qt), trim(r[:db])


def pmod(F, a, m):
    return pdivmod(F, a, m)[1]


def monic(F, a):
    if not a:
        return a
    return pscale(F, F.INV[a[-1]], a)


def pgcd(F, a, b):
    a, b = trim(a[:]), trim(b[:])
    while b:
        a, b = b, pmod(F, a, b)
    return monic(F, a)


def pmulmod(F, a, b, m):
    return pmod(F, pmul(F, a, b), m)


def ppowmod(F, a, e, m):
    r = pmod(F, [1], m)
    a = pmod(F, a, m)
    while e:
        if e & 1:
            r = pmulmod(F, r, a, m)
        e >>= 1
        if e:
            a = pmulmod(F, a, a, m)
    return r


def pderiv(F, a):
    return trim([F.MUL[i % F.p][a[i]] for i in range(1, len(a))])


def xn_minus_1(F, n):
    return [F.NEG[1]] + [0] * (n - 1) + [1]


def prime_factors(n):
    out, d = [], 2
    while d * d <= n:
        if n % d == 0:
            out.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        out.append(n)
    return out


def is_irreducible(F, f):
    """Ben-Or early abort + Rabin's test (Rabin 1980)."""
    n = deg(f)
    if n <= 0:
        return False
    f = monic(F, f)
    if n == 1:
        return True
    x = pmod(F, [0, 1], f)
    h = x
    powers = [x]
    for i in range(1, n + 1):
        h = ppowmod(F, h, F.q, f)
        powers.append(h)
        if i <= n // 2 and deg(pgcd(F, psub(F, h, x), f)) > 0:
            return False
    if psub(F, powers[n], x):
        return False
    for r in prime_factors(n):
        if deg(pgcd(F, psub(F, powers[n // r], x), f)) > 0:
            return False
    return True


def ddf(F, f):
    """Distinct-degree factorisation of a monic squarefree f.
    Returns [(d, product of all irreducible factors of degree d)]."""
    res = []
    fs = monic(F, f)
    h = pmod(F, [0, 1], fs) if deg(fs) >= 1 else []
    d = 0
    while deg(fs) >= 2 * (d + 1):
        d += 1
        h = ppowmod(F, h, F.q, fs)
        g = pgcd(F, psub(F, h, [0, 1]), fs)
        if deg(g) > 0:
            res.append((d, g))
            fs = pdivmod(F, fs, g)[0]
            h = pmod(F, h, fs)
    if deg(fs) > 0:
        res.append((deg(fs), monic(F, fs)))
    return res


def edf(F, f, d, rng):
    """Cantor-Zassenhaus equal-degree splitting of monic f = product of
    distinct irreducibles of degree d."""
    f = monic(F, f)
    n = deg(f)
    if n == d:
        return [f]
    assert n % d == 0
    while True:
        a = trim([rng.randrange(F.q) for _ in range(n)])
        if deg(a) < 1:
            continue
        if F.q % 2 == 1:
            b = psub(F, ppowmod(F, a, (F.q ** d - 1) // 2, f), [1])
        else:  # absolute trace F_{2^{kd}} -> F_2, componentwise
            b, t = [], pmod(F, a, f)
            for _ in range(F.k * d):
                b = padd(F, b, t)
                t = pmulmod(F, t, t, f)
        g = pgcd(F, b, f)
        if 0 < deg(g) < n:
            return edf(F, g, d, rng) + edf(F, pdivmod(F, f, g)[0], d, rng)


def rank_Fq(F, rows):
    M = [r[:] for r in rows if any(r)]
    if not M:
        return 0
    ncols = len(M[0])
    rank = 0
    for col in range(ncols):
        piv = None
        for i in range(rank, len(M)):
            if M[i][col]:
                piv = i
                break
        if piv is None:
            continue
        M[rank], M[piv] = M[piv], M[rank]
        inv = F.INV[M[rank][col]]
        M[rank] = [F.MUL[inv][v] for v in M[rank]]
        pr = M[rank]
        for i in range(len(M)):
            if i != rank and M[i][col]:
                mr = F.MUL[M[i][col]]
                M[i] = [F.SUB[a][mr[b]] for a, b in zip(M[i], pr)]
        rank += 1
        if rank == len(M):
            break
    return rank


def berlekamp_count(F, f):
    """Number of distinct monic irreducible factors of squarefree f:
    n - rank(Q - I), Q the Berlekamp matrix (rows x^{q i} mod f)."""
    n = deg(f)
    X = ppowmod(F, [0, 1], F.q, f)
    rows, P = [], [1]
    for i in range(n):
        v = P + [0] * (n - len(P))
        v[i] = F.SUB[v[i]][1]
        rows.append(v)
        P = pmulmod(F, P, X, f)
    return n - rank_Fq(F, rows)


def factor_xn_minus_1(F, n, rng):
    """Complete factorisation of x^n - 1 over F_q for gcd(n, p) = 1, with
    independent checks. Returns sorted list of monic irreducible factors."""
    f = xn_minus_1(F, n)
    sqf = deg(pgcd(F, f, pderiv(F, f))) == 0
    blocks = ddf(F, f)
    factors = []
    for d, g in blocks:
        factors += edf(F, g, d, rng)
    factors.sort(key=lambda g: (deg(g), g))
    prod = [1]
    for g in factors:
        prod = pmul(F, prod, g)
    checks = {
        "squarefree_gcd_f_fprime_is_1": sqf,
        "product_of_factors_equals_xn_minus_1": prod == f,
        "every_factor_irreducible_rabin": all(is_irreducible(F, g) for g in factors),
        "factors_pairwise_distinct": len(set(tuple(g) for g in factors)) == len(factors),
        "berlekamp_count": berlekamp_count(F, f),
        "ddf_blocks": [(d, deg(g)) for d, g in blocks],
    }
    checks["berlekamp_count_matches"] = checks["berlekamp_count"] == len(factors)
    return factors, checks


# =============================================================================
# 3. F_2[x] on Python ints (bit i = coefficient of x^i)
# =============================================================================
def f2_mul(a, b):
    if a.bit_length() < b.bit_length():
        a, b = b, a
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        b >>= 1
    return r


def f2_mod(a, m):
    dm = m.bit_length() - 1
    la = a.bit_length() - 1
    while la >= dm:
        a ^= m << (la - dm)
        la = a.bit_length() - 1
    return a


def f2_mulmod(a, b, m):
    return f2_mod(f2_mul(a, b), m)


def f2_gcd(a, b):
    while b:
        a, b = b, f2_mod(a, b)
    return a


def f2_powmod(a, e, m):
    r, a = 1, f2_mod(a, m)
    while e:
        if e & 1:
            r = f2_mulmod(r, a, m)
        e >>= 1
        if e:
            a = f2_mulmod(a, a, m)
    return f2_mod(r, m)


def f2_is_irreducible(f):
    n = f.bit_length() - 1
    if n <= 0:
        return False
    if n == 1:
        return True
    x = f2_mod(2, f)
    h, powers = x, [x]
    for i in range(1, n + 1):
        h = f2_mulmod(h, h, f)
        powers.append(h)
        if i <= n // 2 and f2_gcd(h ^ x, f) != 1:
            return False
    if powers[n] != x:
        return False
    for r in prime_factors(n):
        if f2_gcd(powers[n // r] ^ x, f) != 1:
            return False
    return True


def f2_first_sparse_irreducible(n):
    """First irreducible in: trinomials x^n+x^a+1 (a ascending), then
    pentanomials x^n+x^a+x^b+x^c+1 (a>b>c>=1, lexicographic ascending)."""
    for a in range(1, n):
        f = (1 << n) | (1 << a) | 1
        if f2_is_irreducible(f):
            return f
    for a in range(3, n):
        for b in range(2, a):
            for c in range(1, b):
                f = (1 << n) | (1 << a) | (1 << b) | (1 << c) | 1
                if f2_is_irreducible(f):
                    return f
    raise RuntimeError("none found")


def f2_reciprocal(f):
    n = f.bit_length() - 1
    return int(bin(f)[2:].zfill(n + 1)[::-1], 2)


def f2_str(f):
    terms = []
    for i in range(f.bit_length() - 1, -1, -1):
        if (f >> i) & 1:
            terms.append("1" if i == 0 else ("t" if i == 1 else "t^%d" % i))
    return " + ".join(terms)


def f2_rank(vecs):
    basis, r = {}, 0
    for v in vecs:
        while v:
            h = v.bit_length() - 1
            if h in basis:
                v ^= basis[h]
            else:
                basis[h] = v
                r += 1
                break
    return r


def list_to_int(g):  # F_2 list poly -> int
    return sum(1 << i for i, c in enumerate(g) if c)


def pstr(F, g, var="x"):
    terms = []
    for i in range(len(g) - 1, -1, -1):
        c = g[i]
        if c == 0:
            continue
        mon = "1" if i == 0 else (var if i == 1 else "%s^%d" % (var, i))
        if c == 1:
            terms.append(mon)
        else:
            terms.append(("[%d]" % c) + ("" if i == 0 else "*" + mon))
    return " + ".join(terms) if terms else "0"


# =============================================================================
# 4. Divisor-lattice predictions (theory: sigma is cyclic with minimal
#    polynomial x^n - 1, so sigma-stable subspaces <-> monic divisors h of
#    x^n - 1 via V = ker h(sigma), dim V = deg h; sigma|V = id iff h | (x-1).)
# =============================================================================
def lattice_from_factors(F, factors):
    """factors: distinct monic irreducibles, each multiplicity 1 (squarefree case).
    Returns count, sorted dims, sorted faithful dims, d_min."""
    xm1 = [F.NEG[1], 1]
    sums = {(0, False)}
    for g in factors:
        nontriv = (g != xm1)
        sums |= {(s + deg(g), fl or nontriv) for (s, fl) in sums}
    dims = sorted({s for s, _ in sums})
    faithful = sorted({s for s, fl in sums if fl})
    return 2 ** len(factors), dims, faithful, (min(faithful) if faithful else None)


def all_monic_up_to(F, n):
    for d in range(0, n + 1):
        for coeffs in itertools.product(range(F.q), repeat=d):
            yield list(coeffs) + [1]


def lattice_by_divisor_enumeration(F, m):
    """Brute-force enumeration of ALL monic divisors of m (no factoring code)."""
    xm1 = [F.NEG[1], 1]
    divs = [h for h in all_monic_up_to(F, deg(m)) if not pdivmod(F, m, h)[1]]
    dims = sorted({deg(h) for h in divs})
    faithful = sorted({deg(h) for h in divs if pdivmod(F, xm1, h)[1]})  # h does not divide x-1
    return len(divs), dims, faithful, (min(faithful) if faithful else None)


# =============================================================================
# 5. Field model F_{q^n} = F_q[t]/(f) and the q-Frobenius sigma
# =============================================================================
def first_irreducible_Fq(F, n):
    """Deterministic: first irreducible among x^n + c x^j + d (j asc, c asc, d asc),
    then x^n + c1 x^j1 + c2 x^j2 + d."""
    for j in range(0, n):
        for c in range(0 if j else 1, F.q):
            for d in range(1, F.q):
                if j == 0:
                    f = [F.ADD[c][d]] + [0] * (n - 1) + [1]
                    if f[0] == 0:
                        continue
                else:
                    f = [d] + [0] * (j - 1) + [c] + [0] * (n - j - 1) + [1] if c else [d] + [0] * (n - 1) + [1]
                    f = trim(f)
                if deg(f) == n and is_irreducible(F, f):
                    return f
    for j1 in range(2, n):
        for j2 in range(1, j1):
            for c1 in range(1, F.q):
                for c2 in range(1, F.q):
                    for d in range(1, F.q):
                        f = [0] * (n + 1)
                        f[0], f[j2], f[j1], f[n] = d, c2, c1, 1
                        if is_irreducible(F, f):
                            return f
    raise RuntimeError("no irreducible found")


def vecn(a, n):
    return a + [0] * (n - len(a))


def sigma_columns(F, f):
    n = deg(f)
    T = ppowmod(F, [0, 1], F.q, f)
    cols, P = [], [1]
    for _ in range(n):
        cols.append(vecn(P, n))
        P = pmulmod(F, P, T, f)
    return cols


def matvec(F, cols, v):
    n = len(cols)
    w = [0] * n
    ADD, MUL = F.ADD, F.MUL
    for j, vj in enumerate(v):
        if vj:
            row = MUL[vj]
            for i, cij in enumerate(cols[j]):
                if cij:
                    w[i] = ADD[w[i]][row[cij]]
    return w


def vadd(F, a, b):
    return [F.ADD[x][y] for x, y in zip(a, b)]


def vscale(F, c, a):
    row = F.MUL[c]
    return [row[x] for x in a]


# =============================================================================
# Q1 on the real instances
# =============================================================================
def q1_instance(q, n, seed):
    rng = random.Random(seed)
    F = SmallField(q)
    t0 = time.time()
    out = {"q": q, "n": n, "seed": seed, "small_field_model": F.model}
    # --- factor x^n - 1 over F_q (own code) ---
    factors, fchecks = factor_xn_minus_1(F, n, rng)
    out["factorisation_checks"] = fchecks
    out["factor_degrees"] = [deg(g) for g in factors]
    out["factors"] = [pstr(F, g) for g in factors]
    count, dims, faithful, dmin = lattice_from_factors(F, factors)
    out.update({"count": count, "dimensions": dims, "faithful_dimensions": faithful, "d_min": dmin})
    # --- order formula (theory, independent of the factoring code) ---
    divs_n = sorted(sympy.divisors(n))
    own_ord = lambda a, m: next(k for k in range(1, m + 1) if pow(a, k, m) == 1 % m)
    nfac_formula = sum(sympy.totient(d) // (own_ord(q, d) if d > 1 else 1) for d in divs_n)
    out["order_formula"] = {
        "n_is_prime": bool(sympy.isprime(n)),
        "ord_n_q_own": own_ord(q, n),
        "ord_n_q_sympy_n_order": int(n_order(q, n)),
        "number_of_irreducible_factors_sum_phi_d_over_ord_d": int(nfac_formula),
        "predicted_count_2_pow_r": 2 ** int(nfac_formula),
        "matches_factorisation": int(nfac_formula) == len(factors),
    }
    # --- sympy cross-check for prime q ---
    if q in (2, 3):
        x = sympy.symbols("x")
        _, fl = sympy.factor_list(x ** n - 1, modulus=q)
        sdeg = sorted(sympy.Poly(g, x).degree() for g, e in fl for _ in range(e))
        smults = sorted(e for g, e in fl)
        sset = set()
        for g, e in fl:
            cs = [int(c) % q for c in reversed(sympy.Poly(g, x).all_coeffs())]
            cs = monic(F, trim(cs))
            sset.add(tuple(cs))
        out["sympy_crosscheck"] = {
            "sympy_version": sympy.__version__,
            "degrees": sdeg,
            "multiplicities_all_1": all(e == 1 for e in smults),
            "same_factor_set_as_own_code": sset == set(tuple(g) for g in factors),
        }
    # --- concrete field model and sigma ---
    if q == 2:
        fint = f2_first_sparse_irreducible(n)
        out["field_model"] = "F_2[t]/(%s)" % f2_str(fint)
        out["field_model_irreducible_rabin"] = f2_is_irreducible(fint)
        # sigma(z) = z^2 mod f.  Frobenius orbits of the basis t^j.
        orbit = []
        sig_n_is_id = True
        for j in range(n):
            z = f2_mod(1 << j, fint)
            o = [z]
            for i in range(1, n):
                o.append(f2_mulmod(o[-1], o[-1], fint))
            if f2_mulmod(o[-1], o[-1], fint) != z:
                sig_n_is_id = False
            orbit.append(o)
        out["sigma_pow_n_is_identity_on_basis"] = sig_n_is_id
        # Krylov / normal-element check: minimal polynomial of sigma has degree n
        tries = 0
        while True:
            tries += 1
            v = rng.getrandbits(n) or 1
            K = [v]
            for _ in range(n - 1):
                K.append(f2_mulmod(K[-1], K[-1], fint))
            if f2_rank(K) == n:
                break
        out["cyclic_vector_found"] = {"tries": tries, "krylov_rank": n}

        def ker_dim(g):
            gi = list_to_int(g)
            imgs = []
            for j in range(n):
                w = 0
                for i in range(deg(g) + 1):
                    if (gi >> i) & 1:
                        w ^= orbit[j][i] if i < n else orbit[j][i % n]
                imgs.append(w)
            return n - f2_rank(imgs)
    else:
        fl_ = first_irreducible_Fq(F, n)
        out["field_model"] = "F_%d[t]/(%s), F_%d = %s" % (q, pstr(F, fl_, "t"), q, F.model)
        out["field_model_irreducible_rabin"] = is_irreducible(F, fl_)
        cols = sigma_columns(F, fl_)
        # sigma matrix agrees with z -> z^q computed by field arithmetic
        ok = True
        for _ in range(5):
            z = trim([rng.randrange(q) for _ in range(n)])
            if vecn(ppowmod(F, z, q, fl_), n) != matvec(F, cols, vecn(z, n)):
                ok = False
        out["sigma_matrix_matches_z_to_the_q"] = ok
        orbit = []
        sig_n_is_id = True
        for j in range(n):
            e = [0] * n
            e[j] = 1
            o = [e]
            for i in range(1, n):
                o.append(matvec(F, cols, o[-1]))
            if matvec(F, cols, o[-1]) != e:
                sig_n_is_id = False
            orbit.append(o)
        out["sigma_pow_n_is_identity_on_basis"] = sig_n_is_id
        tries = 0
        while True:
            tries += 1
            v = [rng.randrange(q) for _ in range(n)]
            K = [v]
            for _ in range(n - 1):
                K.append(matvec(F, cols, K[-1]))
            if rank_Fq(F, K) == n:
                break
        out["cyclic_vector_found"] = {"tries": tries, "krylov_rank": n}

        def ker_dim(g):
            imgs = []
            for j in range(n):
                w = [0] * n
                for i, gi in enumerate(g):
                    if gi:
                        w = vadd(F, w, vscale(F, gi, orbit[j][i % n]))
                imgs.append(w)
            return n - rank_Fq(F, imgs)
    # per-factor kernel dimensions on the concrete model
    xm1 = [F.NEG[1], 1]
    kd = []
    for g in factors:
        rec = {"factor_degree": deg(g), "dim_ker_g_sigma": ker_dim(g)}
        if g != xm1:
            # ker g(sigma) meets ker(sigma - 1) = F_q trivially  <=>  dim ker (g*(x-1))(sigma) = deg g + 1
            rec["dim_ker_g_times_x_minus_1"] = ker_dim(pmul(F, g, xm1))
            rec["sigma_restricted_not_identity"] = rec["dim_ker_g_times_x_minus_1"] == deg(g) + 1 and rec["dim_ker_g_sigma"] > 0
        kd.append(rec)
    out["kernel_dims_per_factor"] = kd
    out["kernel_dims_equal_factor_degrees"] = all(r["dim_ker_g_sigma"] == r["factor_degree"] for r in kd)
    out["dim_ker_sigma_minus_1"] = ker_dim(xm1)
    out["seconds"] = round(time.time() - t0, 3)
    return out


