# Q1 controls: brute-force enumeration of ALL F_q-subspaces on small instances
# =============================================================================
def enumerate_rref(F, n):
    q = F.q
    for k in range(n + 1):
        for piv in itertools.combinations(range(n), k):
            ps = set(piv)
            free = [(i, c) for i in range(k) for c in range(piv[i] + 1, n) if c not in ps]
            for vals in itertools.product(range(q), repeat=len(free)):
                rows = [[0] * n for _ in range(k)]
                for i in range(k):
                    rows[i][piv[i]] = 1
                for (i, c), v in zip(free, vals):
                    rows[i][c] = v
                yield piv, rows


def in_span_rref(F, piv, rows, w):
    w = w[:]
    for p, row in zip(piv, rows):
        c = w[p]
        if c:
            mr = F.MUL[c]
            w = [F.SUB[a][mr[b]] for a, b in zip(w, row)]
    return not any(w)


def gaussian_total(q, n):
    def gb(n, k):
        num = den = 1
        for i in range(k):
            num *= q ** (n - i) - 1
            den *= q ** (i + 1) - 1
        return num // den
    return sum(gb(n, k) for k in range(n + 1))


def brute_stable(F, cols, n):
    total = 0
    stable = 0
    dims, fdims = set(), set()
    for piv, rows in enumerate_rref(F, n):
        total += 1
        imgs = [matvec(F, cols, r) for r in rows]
        if all(in_span_rref(F, piv, rows, w) for w in imgs):
            stable += 1
            dims.add(len(rows))
            if any(w != r for w, r in zip(imgs, rows)):
                fdims.add(len(rows))
    return total, stable, sorted(dims), sorted(fdims), (min(fdims) if fdims else None)


def minpoly_brute(F, cols, n):
    """Minimal polynomial of the matrix with the given columns, by enumerating
    monic h of increasing degree and testing h(M) = 0 on the basis."""
    basis = []
    for j in range(n):
        e = [0] * n
        e[j] = 1
        basis.append(e)
    for d in range(1, n + 1):
        for coeffs in itertools.product(range(F.q), repeat=d):
            h = list(coeffs) + [1]
            ok = True
            for e in basis:
                w = [0] * n
                pw = e
                for i, hi in enumerate(h):
                    if hi:
                        w = vadd(F, w, vscale(F, hi, pw))
                    pw = matvec(F, cols, pw)
                if any(w):
                    ok = False
                    break
            if ok:
                return h
    raise RuntimeError


def q1_controls(seed):
    rng = random.Random(seed)
    pos = []
    cases = [(2, 2), (2, 3), (2, 4), (2, 5), (2, 6), (2, 7), (3, 2), (3, 3), (3, 4), (3, 5),
             (4, 2), (4, 3), (4, 4), (8, 2), (8, 3)]
    for q, n in cases:
        F = SmallField(q)
        f = first_irreducible_Fq(F, n)
        cols = sigma_columns(F, f)
        total, stable, dims, fdims, dmin = brute_stable(F, cols, n)
        pc, pdims, pf, pdmin = lattice_by_divisor_enumeration(F, xn_minus_1(F, n))
        rec = {"q": q, "n": n, "field_model": "F_%d[t]/(%s)" % (q, pstr(F, f, "t")),
               "gcd_n_p": math.gcd(n, F.p),
               "brute_total_subspaces": total, "gaussian_binomial_total": gaussian_total(q, n),
               "brute_stable_count": stable, "brute_dims": dims, "brute_faithful_dims": fdims,
               "brute_d_min": dmin,
               "divisor_lattice_count": pc, "divisor_lattice_dims": pdims,
               "divisor_lattice_faithful_dims": pf, "divisor_lattice_d_min": pdmin}
        if math.gcd(n, F.p) == 1:
            fac, _ = factor_xn_minus_1(F, n, rng)
            c2, d2, f2, m2 = lattice_from_factors(F, fac)
            rec.update({"factor_code_count": c2, "factor_code_dims": d2, "factor_code_d_min": m2})
        rec["agree"] = (total == rec["gaussian_binomial_total"] and stable == pc and dims == pdims
                        and fdims == pf and dmin == pdmin
                        and (math.gcd(n, F.p) != 1 or (rec["factor_code_count"] == stable
                                                       and rec["factor_code_dims"] == dims
                                                       and rec["factor_code_d_min"] == dmin)))
        pos.append(rec)
    # negative control 1: identity map (not cyclic) -- the divisor-lattice
    # prediction for its minimal polynomial (x - 1) must FAIL against brute force.
    neg = []
    for q, n in [(2, 4), (3, 3), (4, 2)]:
        F = SmallField(q)
        cols = [[1 if i == j else 0 for i in range(n)] for j in range(n)]
        total, stable, dims, fdims, dmin = brute_stable(F, cols, n)
        mp = minpoly_brute(F, cols, n)
        pc, _, _, _ = lattice_by_divisor_enumeration(F, mp)
        neg.append({"operator": "identity", "q": q, "n": n, "minpoly": pstr(F, mp),
                    "brute_stable_count": stable, "divisor_lattice_count_of_minpoly": pc,
                    "brute_faithful_dims": fdims,
                    "prediction_fails_as_expected": stable != pc})
    # null-object control 2: seeded random invertible matrices of the same shape.
    # Expect: brute count == #divisors(minpoly) exactly when the matrix is cyclic.
    nulls = []
    for q, n, reps in [(2, 4, 6), (2, 5, 4), (3, 3, 6)]:
        F = SmallField(q)
        got = 0
        while got < reps:
            cols = [[rng.randrange(q) for _ in range(n)] for _ in range(n)]
            if rank_Fq(F, cols) < n:
                continue
            got += 1
            total, stable, dims, fdims, dmin = brute_stable(F, cols, n)
            mp = minpoly_brute(F, cols, n)
            pc, _, _, _ = lattice_by_divisor_enumeration(F, mp)
            cyc = deg(mp) == n
            nulls.append({"q": q, "n": n, "minpoly": pstr(F, mp), "cyclic": cyc,
                          "brute_stable_count": stable, "divisor_count_of_minpoly": pc,
                          "match": stable == pc,
                          "consistent_with_theory": (stable == pc) if cyc else (stable > pc)})
    # null-object control 3: rejection-sampled NON-cyclic, non-scalar invertible
    # matrices (random matrices are cyclic with high probability, so the
    # non-cyclic side must be sampled for deliberately).  Expect brute > #divisors.
    noncyc = []
    for q, n, want in [(2, 4, 4), (3, 3, 3), (2, 5, 3)]:
        F = SmallField(q)
        got = sampled = cyclic_seen = 0
        while got < want and sampled < 20000:
            cols = [[rng.randrange(q) for _ in range(n)] for _ in range(n)]
            if rank_Fq(F, cols) < n:
                continue
            sampled += 1
            mp = minpoly_brute(F, cols, n)
            if deg(mp) == n:
                cyclic_seen += 1
                continue
            if deg(mp) == 1:  # scalar matrix; excluded (already covered by identity control)
                continue
            got += 1
            total, stable, dims, fdims, dmin = brute_stable(F, cols, n)
            pc, _, _, _ = lattice_by_divisor_enumeration(F, mp)
            noncyc.append({"q": q, "n": n, "minpoly": pstr(F, mp), "cyclic": False,
                           "brute_stable_count": stable, "divisor_count_of_minpoly": pc,
                           "consistent_with_theory": stable > pc,
                           "invertible_matrices_sampled_so_far": sampled,
                           "cyclic_among_sampled_so_far": cyclic_seen})
    return {"positive": pos, "negative_identity": neg, "null_random_matrices": nulls,
            "null_noncyclic_matrices": noncyc}


