def q2(q1res):
    mpmath.mp.dps = 50
    getcontext().prec = 60
    cells = []
    for n in [113, 127, 131, 163]:
        r = q1res[(2, n)]
        faithful = r["faithful_dimensions"]
        for m in [2, 3, 4, 5]:
            lstar = -(-n // m)
            assert lstar == math.ceil(Fraction(n, m))
            cand = [d for d in faithful if d >= lstar]
            lp = min(cand) if cand else None
            if lp is None:
                cells.append({"n": n, "m": m, "l_star": lstar, "l_prime": "none", "penalty": "none",
                              "margin_bits": "none", "verdict": "loss"})
                continue
            pen = lp - lstar
            mg = mpmath.log(n, 2) - pen * mpmath.log(2, 2)
            mg_dec = (Decimal(n).ln() / Decimal(2).ln()) - pen * (Decimal(2).ln() / Decimal(2).ln())
            mg_float = math.log2(n) - pen * math.log2(2)
            cells.append({
                "n": n, "m": m, "l_star": lstar, "l_prime": lp, "penalty": pen,
                "margin_bits": mpmath.nstr(mg, 25),
                "margin_bits_decimal_crosscheck": str(+mg_dec)[:30],
                "margin_bits_float64": repr(mg_float),
                "abs_diff_mpmath_vs_decimal": mpmath.nstr(abs(mg - mpmath.mpf(str(mg_dec))), 3),
                "verdict": "win" if mg > 0 else "loss",
            })
    return cells


