def f2_field_tables(n, f):
    N = (1 << n) - 1
    pf = prime_factors(N)
    g = 2
    while True:
        if all(f2_powmod(g, N // r, f) != 1 for r in pf):
            break
        g += 1
    exp = [1] * N
    for i in range(1, N):
        exp[i] = f2_mulmod(exp[i - 1], g, f)
    lg = [None] * (N + 1)
    for i, e in enumerate(exp):
        assert lg[e] is None
        lg[e] = i
    assert all(lg[a] is not None for a in range(1, N + 1))
    return g, exp, lg


def q3_model(n, f, seed):
    rng = random.Random(seed)
    t0 = time.time()
    N = (1 << n) - 1
    Q = 1 << n
    out = {"n": n, "field_model": "F_2[t]/(%s)" % f2_str(f), "irreducible_rabin": f2_is_irreducible(f)}
    assert out["irreducible_rabin"]
    g, exp, lg = f2_field_tables(n, f)
    out["primitive_element_used_for_tables"] = f2_str(g) if g > 1 else "1"
    mul = lambda a, b: f2_mulmod(a, b, f)
    # table multiplication agrees with direct multiplication
    ok = True
    for _ in range(20000):
        a, b = rng.randrange(1, Q), rng.randrange(1, Q)
        if exp[(lg[a] + lg[b]) % N] != mul(a, b):
            ok = False
    out["log_table_mul_matches_direct_20000_random_pairs"] = ok
    sq = [mul(x, x) for x in range(Q)]

    def trace(x):
        s, z = 0, x
        for _ in range(n):
            s ^= z
            z = mul(z, z)
        return s

    tr = [trace(x) for x in range(Q)]
    assert set(tr) <= {0, 1}
    out["trace_zero_hyperplane_size"] = tr.count(0)
    # --- Method A: exhaustive over all (x, y) pairs (log tables for the product) ---
    E2 = [exp[(2 * j) % N] for j in range(N)]  # (g^j)^2
    pts = []
    for x in range(Q):
        c = mul(mul(x, x), x) ^ 1  # x^3 + a2 x^2 + a4 x + a6 with a2=a4=0, a6=1
        if c == 0:  # y = 0:  0^2 + x*0 = 0
            pts.append((x, 0))
        if x == 0:
            pts += [(0, exp[j]) for j in range(N) if E2[j] == c]
        else:
            lx = lg[x]
            R = exp[lx:] + exp[:lx]  # R[j] = x * g^j
            pts += [(x, exp[j]) for j in range(N) if E2[j] ^ R[j] == c]
    # every point verified with direct arithmetic: y^2 + a1 x y + a3 y = x^3 + a2 x^2 + a4 x + a6
    assert all(mul(y, y) ^ mul(x, y) == mul(mul(x, x), x) ^ 1 for x, y in pts)
    affine = len(pts)
    out["method_A_exhaustive_affine_points"] = affine
    out["group_order"] = affine + 1
    # optional fully naive double loop (no tables) for n <= 11
    if n <= 11:
        cnt = 0
        for x in range(Q):
            c = mul(mul(x, x), x) ^ 1
            for y in range(Q):
                if sq[y] ^ mul(x, y) == c:
                    cnt += 1
        out["naive_double_loop_affine_points"] = cnt
    FV = [(x, y) for (x, y) in pts if tr[x] == 0]
    FVs = set(FV)
    out["F_V_size"] = len(FV)
    out["f"] = sum(1 for (x, y) in FV if x in (0, 1) and y in (0, 1))
    out["F_V_points_with_both_coords_in_F2"] = [[x, y] for (x, y) in FV if x in (0, 1) and y in (0, 1)]
    # pi orbits
    pi = lambda P: (sq[P[0]], sq[P[1]])
    assert all(pi(P) in FVs for P in FV)
    seen, hist = set(), {}
    for P in FV:
        if P in seen:
            continue
        L, Qp = 0, P
        while True:
            seen.add(Qp)
            L += 1
            Qp = pi(Qp)
            if Qp == P:
                break
        hist[L] = hist.get(L, 0) + 1
    orbits = sum(hist.values())
    out["orbits"] = orbits
    out["orbit_length_histogram"] = {str(k): v for k, v in sorted(hist.items())}
    out["ratio_fraction"] = "%d/%d" % (Fraction(len(FV), orbits).numerator, Fraction(len(FV), orbits).denominator)
    mpmath.mp.dps = 40
    out["ratio"] = mpmath.nstr(mpmath.mpf(len(FV)) / orbits, 25)
    # --- Method B: per-x solution count by the trace criterion (no enumeration of y) ---
    inv = lambda a: f2_powmod(a, Q - 2, f)
    totB, fvB = 0, 0
    for x in range(Q):
        if x == 0:
            k = 1  # y^2 = 1 has exactly one root
        else:
            ix = inv(x)
            k = 2 if trace(x ^ mul(ix, ix)) == 0 else 0  # z^2 + z = x + x^-2
        totB += k
        if tr[x] == 0:
            fvB += k
    out["method_B_trace_criterion_affine_points"] = totB
    out["method_B_trace_criterion_F_V_size"] = fvB
    # Kloosterman sum K = sum_{x != 0} (-1)^{Tr(x + 1/x)}
    K = sum(1 - 2 * trace(x ^ inv(x)) for x in range(1, Q))
    out["kloosterman_sum_K"] = K
    out["seconds"] = round(time.time() - t0, 3)
    return out


def q3(seed):
    # Method C: Frobenius trace over F_2 and the recurrence s_k = t s_{k-1} - 2 s_{k-2}
    e2 = [(x, y) for x in (0, 1) for y in (0, 1) if (y * y + x * y) % 2 == (x ** 3 + 1) % 2]
    nE2 = len(e2) + 1
    t = 2 + 1 - nE2
    s = [2, t]
    for k in range(2, 14):
        s.append(t * s[-1] - 2 * s[-2])
    res = {"E_over_F2_affine_points": e2, "E_F2_order": nE2, "frobenius_trace_t": t,
           "s_k_alpha_pow_k_plus_beta_pow_k": s, "per_n": {}}
    for n in [7, 11, 13]:
        fa = f2_first_sparse_irreducible(n)
        fb = f2_reciprocal(fa)
        ma = q3_model(n, fa, seed + n)
        mb = q3_model(n, fb, seed + 100 + n)
        pred_order = 2 ** n + 1 - s[n]
        pred_FV = 1 + (2 ** n - 3 - s[n]) // 2
        assert (2 ** n - 3 - s[n]) % 2 == 0
        keys = ["F_V_size", "f", "orbits", "orbit_length_histogram", "ratio", "ratio_fraction", "group_order",
                "method_A_exhaustive_affine_points", "method_B_trace_criterion_affine_points",
                "method_B_trace_criterion_F_V_size", "kloosterman_sum_K"]
        res["per_n"][str(n)] = {
            "model_A": ma, "model_B": mb,
            "models_agree_on_all_quantities": all(ma[k] == mb[k] for k in keys),
            "method_C_group_order_2^n+1-s_n": pred_order,
            "method_D_closed_form_F_V_size_1+(2^n-3-s_n)/2": pred_FV,
            "kloosterman_equals_minus_s_n": ma["kloosterman_sum_K"] == -s[n],
            "all_methods_agree": (ma["group_order"] == pred_order == ma["method_B_trace_criterion_affine_points"] + 1
                                  and ma["F_V_size"] == pred_FV == ma["method_B_trace_criterion_F_V_size"]
                                  and ma.get("naive_double_loop_affine_points", ma["method_A_exhaustive_affine_points"])
                                  == ma["method_A_exhaustive_affine_points"]),
        }
    return res


