        chk.append(("Q1ctl_null_%d_%d_%d" % (r["q"], r["n"], i), r["consistent_with_theory"]))
    for i, r in enumerate(ctl["null_noncyclic_matrices"]):
        chk.append(("Q1ctl_noncyclic_%d_%d_%d" % (r["q"], r["n"], i), r["consistent_with_theory"]))
    chk.append(("Q1ctl_noncyclic_count", len(ctl["null_noncyclic_matrices"]) == 10))
    for (q, n), r in q1res.items():
        fc = r["factorisation_checks"]
        tag = "Q1_%d_%d_" % (q, n)
        chk += [(tag + "squarefree", fc["squarefree_gcd_f_fprime_is_1"]),
                (tag + "product", fc["product_of_factors_equals_xn_minus_1"]),
                (tag + "irreducible_factors", fc["every_factor_irreducible_rabin"]),
                (tag + "distinct_factors", fc["factors_pairwise_distinct"]),
                (tag + "berlekamp", fc["berlekamp_count_matches"]),
                (tag + "order_formula", r["order_formula"]["matches_factorisation"]),
                (tag + "order_own_eq_sympy", r["order_formula"]["ord_n_q_own"] == r["order_formula"]["ord_n_q_sympy_n_order"]),
                (tag + "field_model_irreducible", r["field_model_irreducible_rabin"]),
                (tag + "sigma_n_identity", r["sigma_pow_n_is_identity_on_basis"]),
                (tag + "cyclic_vector", r["cyclic_vector_found"]["krylov_rank"] == n),
                (tag + "kernel_dims", r["kernel_dims_equal_factor_degrees"]),
                (tag + "fixed_space_is_Fq", r["dim_ker_sigma_minus_1"] == 1),
                (tag + "faithful_kernels", all(k.get("sigma_restricted_not_identity", True) for k in r["kernel_dims_per_factor"]))]
        if "sigma_matrix_matches_z_to_the_q" in r:
            chk.append((tag + "sigma_matrix", r["sigma_matrix_matches_z_to_the_q"]))
        if "sympy_crosscheck" in r:
            chk.append((tag + "sympy_same_factors", r["sympy_crosscheck"]["same_factor_set_as_own_code"]))
    for c in q2res:
        if c["l_prime"] != "none":
            chk.append(("Q2_%d_%d_mpmath_vs_decimal" % (c["n"], c["m"]),
                        mpmath.mpf(c["abs_diff_mpmath_vs_decimal"]) < mpmath.mpf("1e-40")))
    for n, r in q3res["per_n"].items():
        chk += [("Q3_%s_models_agree" % n, r["models_agree_on_all_quantities"]),
                ("Q3_%s_all_methods_agree" % n, r["all_methods_agree"]),
                ("Q3_%s_kloosterman" % n, r["kloosterman_equals_minus_s_n"]),
                ("Q3_%s_tablemul_A" % n, r["model_A"]["log_table_mul_matches_direct_20000_random_pairs"]),
                ("Q3_%s_tablemul_B" % n, r["model_B"]["log_table_mul_matches_direct_20000_random_pairs"])]
    failed = [k for k, v in chk if not v]
    results["internal_checks"] = {"n_checks": len(chk), "failed": failed, "all_pass": not failed}
    log("== INTERNAL CHECKS: %d run, failed: %s ==" % (len(chk), failed))
    results["total_seconds"] = round(time.time() - T0, 2)
    import resource
    results["peak_rss_kib"] = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    results["cpu_user_seconds"] = round(resource.getrusage(resource.RUSAGE_SELF).ru_utime, 2)
    log("=== RESULTS JSON ===")
    print(json.dumps(results, indent=1, sort_keys=True, default=str))


